-- key: id
SELECT "id", "patch", "min_players_per_team", "max_players_per_team", "min_level", "max_level", "alliance_win_spell", "alliance_lose_spell", "horde_win_spell", "horde_lose_spell", "alliance_start_location", "horde_start_location", "player_loot_id" FROM (SELECT "id", "patch", "min_players_per_team", "max_players_per_team", "min_level", "max_level", "alliance_win_spell", "alliance_lose_spell", "horde_win_spell", "horde_lose_spell", "alliance_start_location", "horde_start_location", "player_loot_id", ROW_NUMBER() OVER (PARTITION BY "id" ORDER BY "patch" DESC, rowid DESC) AS __rn FROM "battleground_template" WHERE "patch" <= 10) WHERE __rn = 1
